'use client'

import * as React from 'react'
import { ArrowRight } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { Badge } from '@/registry/satin/ui/badge'
import { Progress } from '@/registry/satin/ui/progress'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * AgentSuggestion, 1:1 with the uiKit `AgentSuggestion` set (🆕 agent suggestions, 4126:3903):
 * something the agent has prepared and the user only approves — an email, a reply, a meeting,
 * tasks, an insight, an edit or a CRM update.
 *
 * A bg/card card, border/subtle, radius-xl, shadow-sm, 12px in and 12px between its parts:
 *
 * - the kind row: what it is, as a neutral Large Outline Badge (white, border/default) with a 14px icon
 *   or app logo (`kind`, `icon`), and on the right who or what it concerns (`meta`: avatars, a
 *   small Badge with the source);
 * - `title` in Label/lg (14/14 medium) and `description` in Body/lg text/muted, 8px apart;
 * - `children`: whatever the suggestion needs (time slots, tasks, a diff, changed fields);
 * - `actions`, right-aligned 8px apart, 4px further down: a secondary or tertiary button and the
 *   primary one that carries it out.
 *
 * The parts below cover the usual bodies: `AgentSuggestionQuote` (the message being answered),
 * `AgentSuggestionMetric` (a number against a limit), `AgentSuggestionDiff` (old text → new) and
 * `AgentSuggestionChanges` (fields from → to).
 */
export interface AgentSuggestionProps extends Omit<React.ComponentProps<'section'>, 'title'> {
  /** What kind of suggestion: "Email suggestion", "Next steps", "CRM update". */
  kind: React.ReactNode
  /** A 14px icon or app logo before the kind. */
  icon?: React.ReactNode
  /** Right of the kind: avatars of the people it concerns, or a small Badge with the source. */
  meta?: React.ReactNode
  title?: React.ReactNode
  description?: React.ReactNode
  /** Buttons, right-aligned: the alternative first, the primary action last. */
  actions?: React.ReactNode
}

export function AgentSuggestion({
  kind,
  icon,
  meta,
  title,
  description,
  actions,
  children,
  className,
  ...props
}: AgentSuggestionProps) {
  const titleId = React.useId()
  return (
    <section
      data-slot="agent-suggestion"
      aria-labelledby={title ? titleId : undefined}
      className={cn(
        'sa:flex sa:w-full sa:max-w-[400px] sa:flex-col sa:gap-3 sa:rounded-xl sa:border sa:border-border-subtle sa:bg-bg-card sa:p-3 sa:text-text-default sa:[box-shadow:0_1px_3px_0_var(--effect-shadow-sm),0_1px_2px_-1px_var(--effect-shadow-sm)]',
        className,
      )}
      {...props}
    >
      <div className="sa:flex sa:min-h-6 sa:items-center sa:gap-1.5">
        <div className="sa:flex sa:min-w-0 sa:flex-1">
          <Badge
            size="lg"
            tone="neutral"
            variant="outline"
            className="sa:max-w-full sa:[&_img]:size-3.5 sa:[&_img]:shrink-0"
          >
            {icon}
            <span className="sa:truncate">{kind}</span>
          </Badge>
        </div>
        {meta && <div className="sa:flex sa:shrink-0 sa:items-center">{meta}</div>}
      </div>

      {(title || description) && (
        <div className="sa:flex sa:flex-col sa:gap-2">
          {title && (
            <div id={titleId} className="sa:text-base sa:leading-[14px] sa:font-medium sa:tracking-normal sa:text-text-default">
              {title}
            </div>
          )}
          {description && <div className="sa:text-base sa:text-text-muted">{description}</div>}
        </div>
      )}

      {children}

      {actions && <div className="sa:flex sa:flex-wrap sa:items-center sa:justify-end sa:gap-2 sa:pt-1">{actions}</div>}
    </section>
  )
}

/** The message the suggestion answers: who sent it and what they wrote, on bg/muted. */
export function AgentSuggestionQuote({
  from,
  avatar,
  children,
  className,
}: {
  /** The sender's name. */
  from: React.ReactNode
  /** A 20px Avatar. */
  avatar?: React.ReactNode
  children: React.ReactNode
  className?: string
}) {
  return (
    <blockquote data-slot="agent-suggestion-quote" className={cn('sa:m-0 sa:flex sa:flex-col sa:gap-1 sa:rounded-lg sa:bg-bg-muted sa:px-3 sa:py-2', className)}>
      <div className="sa:flex sa:items-center sa:gap-1.5">
        {avatar}
        <span className="sa:text-xs sa:leading-3 sa:font-medium sa:tracking-normal sa:text-text-default">{from}</span>
      </div>
      <p className="sa:m-0 sa:text-base sa:text-text-muted">{children}</p>
    </blockquote>
  )
}

/** A number against its limit: the value in Display/sm, its unit, and a 6px bar of how much is used. */
export function AgentSuggestionMetric({
  value,
  unit,
  used,
  max,
  className,
}: {
  /** As shown: "47 / 50". */
  value: React.ReactNode
  unit?: React.ReactNode
  /** With `max`, draws the bar. */
  used?: number
  max?: number
  className?: string
}) {
  return (
    <div data-slot="agent-suggestion-metric" className={cn('sa:flex sa:flex-col sa:gap-2', className)}>
      <div className="sa:flex sa:items-baseline sa:gap-2">
        <span className="sa:text-2xl sa:leading-[1.5] sa:font-medium sa:tabular-nums">{value}</span>
        {unit && <span className="sa:text-base sa:text-text-muted">{unit}</span>}
      </div>
      {used != null && max != null && (
        <Progress
          value={used}
          max={max}
          showValue={false}
          aria-label={typeof unit === 'string' ? unit : undefined}
          className="sa:[&_[role=progressbar]]:h-1.5"
        />
      )}
    </div>
  )
}

/** Old text struck through on bg/muted, the new text in status/green below it. */
export function AgentSuggestionDiff({ before, after, className }: { before: React.ReactNode; after: React.ReactNode; className?: string }) {
  const labels = useSatinLabels()
  return (
    <div data-slot="agent-suggestion-diff" className={cn('sa:flex sa:flex-col sa:gap-1 sa:text-base', className)}>
      <del className="sa:rounded-lg sa:bg-bg-muted sa:px-2 sa:py-1.5 sa:text-text-muted">
        <span className="sa:sr-only">{labels.remove}: </span>
        {before}
      </del>
      <ins className="sa:rounded-lg sa:bg-status-green-bg sa:px-2 sa:py-1.5 sa:text-status-green-fg sa:no-underline">
        <span className="sa:sr-only">{labels.add}: </span>
        {after}
      </ins>
    </div>
  )
}

export interface AgentSuggestionChange {
  field: React.ReactNode
  from?: React.ReactNode
  /** A string reads as Body/md Strong; pass a Badge for a stage or status. */
  to: React.ReactNode
}

/** Fields the agent will change: name, the old value struck through, an arrow and the new one. */
export function AgentSuggestionChanges({ changes, className }: { changes: AgentSuggestionChange[]; className?: string }) {
  return (
    <dl data-slot="agent-suggestion-changes" className={cn('sa:m-0 sa:flex sa:flex-col sa:gap-2 sa:text-base', className)}>
      {changes.map((c, i) => (
        <div key={i} className="sa:flex sa:min-h-[21px] sa:items-center sa:gap-2">
          <dt className="sa:w-[88px] sa:shrink-0 sa:text-text-muted">{c.field}</dt>
          <dd className="sa:m-0 sa:flex sa:min-w-0 sa:items-center sa:gap-2">
            {c.from != null && (
              <>
                <del className="sa:text-text-subtle">{c.from}</del>
                <ArrowRight aria-hidden className="sa:size-4 sa:shrink-0 sa:text-text-subtle sa:[stroke-width:1.875]" />
              </>
            )}
            {typeof c.to === 'string' ? <span className="sa:font-medium sa:text-text-default">{c.to}</span> : c.to}
          </dd>
        </div>
      ))}
    </dl>
  )
}
